#include <fstream>
#include <iostream>

int main() {
    {
        std::ofstream salida{"serie_lgp.txt"};
        if (!salida) {
            std::cout << "Initial open error";
            return 1;
        }
        salida << "1 2";
        salida.close();
        if (!salida) {
            std::cout << "Initial write error";
            return 1;
        }
    }
    {
        std::ofstream salida{"serie_lgp.txt", std::ios::app};
        if (!salida) {
            std::cout << "Second open error";
            return 1;
        }
        salida << " 3";
        salida.close();
        if (!salida) {
            std::cout << "Second write error";
            return 1;
        }
    }
    std::ifstream entrada{"serie_lgp.txt"};
    if (!entrada) {
        std::cout << "Input open error";
        return 1;
    }
    int a{0};
    int b{0};
    int c{0};
    if (!(entrada >> a >> b >> c)) {
        std::cout << "Incomplete read";
        return 1;
    }
    std::cout << "Total=" << a + b + c;
    return 0;
}

